// Generates src/LinkedArtNet/Fluent/FluentExtensions.g.cs: one With{Property}() extension method family per
// settable model property, by reflecting over the built LinkedArtNet assembly. Run after changing the model:
//   dotnet run --project tools/FluentGen
// FluentApiTests checks the generated file covers every eligible property.
//
// Rules (shared with FluentApiTests):
//   - every public settable instance property declared on a LinkedArtObject subclass (or the base), except
//     those with hand-written helpers in LinkedArtExtensions/DimensionExtensions: Context, Id, Type, Label,
//     Content, ClassifiedAs, Language, Technique, MadeOf, Dimension.
//   - List<TItem>: With{P}<T>(this T, params TItem[]) appends; plus With{P}<T>(this T, Action<TItem>) when
//     TItem is a concrete model class, which creates, configures and appends one item.
//   - model-typed single property: With{P}<T>(this T, TItem) sets; plus the Action<TItem> form when concrete.
//   - scalar: With{P}<T>(this T, TItem) sets (nullable value types take the non-nullable value).
//   - When several unrelated classes declare the same property with the same type, C# cannot distinguish the
//     methods by constraint alone, so the generator emits an interface IHas{P} (or IHas{P}{Type} when the same
//     name has several types), adds it to each class through a partial declaration, and constrains the single
//     method to that interface.

using System.Reflection;
using System.Text;
using LinkedArtNet;

var repoRoot = args.Length > 0 ? args[0] : FindRepoRoot();
var outPath = Path.Combine(repoRoot, "src", "LinkedArtNet", "Fluent", "FluentExtensions.g.cs");

var code = FluentGenerator.Generate();
Directory.CreateDirectory(Path.GetDirectoryName(outPath)!);
File.WriteAllText(outPath, code, new UTF8Encoding(false));
Console.WriteLine($"Wrote {Path.GetRelativePath(repoRoot, outPath)} ({code.Count(c => c == '\n')} lines)");

static string FindRepoRoot()
{
    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "linked-art-net.slnx"))) dir = dir.Parent;
    return dir?.FullName ?? throw new InvalidOperationException("Run from within the repository, or pass its root as the first argument.");
}

public static class FluentGenerator
{
    public static readonly HashSet<string> HandWritten = ["Context", "Id", "Type", "Label", "Content", "ClassifiedAs", "Language", "Technique", "MadeOf", "Dimension"];

    public static IEnumerable<System.Type> ModelClasses() =>
        typeof(LinkedArtObject).Assembly.GetTypes()
            .Where(t => t.IsClass && typeof(LinkedArtObject).IsAssignableFrom(t) && t.Namespace == "LinkedArtNet")
            .OrderBy(t => t.Name);

    public static IEnumerable<PropertyInfo> EligibleProperties(System.Type cls) =>
        cls.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
            .Where(p => p.SetMethod is { IsPublic: true } && !HandWritten.Contains(p.Name))
            .OrderBy(p => p.Name);

    private sealed record Group(string PropertyName, System.Type PropertyType, List<System.Type> Classes)
    {
        public bool Shared => Classes.Count > 1;
        public string? InterfaceName { get; set; }
    }

    public static string Generate()
    {
        // Group (property name, property type) across classes.
        var groups = ModelClasses()
            .SelectMany(c => EligibleProperties(c).Select(p => (Class: c, Property: p)))
            .GroupBy(x => (x.Property.Name, x.Property.PropertyType))
            .Select(g => new Group(g.Key.Name, g.Key.PropertyType, g.Select(x => x.Class).OrderBy(c => c.Name).ToList()))
            .OrderBy(g => g.PropertyName).ThenBy(g => TypeName(g.PropertyType))
            .ToList();

        // Interface names: IHas{Prop}, or IHas{Prop}{ItemType} when the same property name has several types.
        foreach (var byName in groups.Where(g => g.Shared).GroupBy(g => g.PropertyName))
        {
            var multiple = byName.Count() > 1 || groups.Any(g => g.PropertyName == byName.Key && !g.Shared);
            foreach (var g in byName)
                g.InterfaceName = multiple ? $"IHas{g.PropertyName}{Suffix(g.PropertyType)}" : $"IHas{g.PropertyName}";
        }

        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated>");
        sb.AppendLine("//     Generated by tools/FluentGen from the model classes. Do not edit; change the model and rerun the tool.");
        sb.AppendLine("// </auto-generated>");
        sb.AppendLine();
        sb.AppendLine("#nullable enable");
        sb.AppendLine();
        sb.AppendLine("namespace LinkedArtNet;");
        sb.AppendLine();

        // Interfaces for shared properties (skipping any already hand-written in the model, e.g. IHasReferredToBy).
        foreach (var g in groups.Where(g => g.Shared && typeof(LinkedArtObject).Assembly.GetType("LinkedArtNet." + g.InterfaceName) is null))
        {
            sb.AppendLine($"/// <summary>Classes with a <c>{JsonName(g)}</c> property of type {TypeName(g.PropertyType)}: {string.Join(", ", g.Classes.Select(c => c.Name))}.</summary>");
            sb.AppendLine($"public interface {g.InterfaceName}");
            sb.AppendLine("{");
            var propType = TypeName(g.PropertyType); sb.AppendLine($"    {propType}{(propType.EndsWith('?') ? "" : "?")} {g.PropertyName} {{ get; set; }}");
            sb.AppendLine("}");
            sb.AppendLine();
        }

        // Partial declarations adding the interfaces.
        foreach (var cls in ModelClasses())
        {
            var interfaces = groups.Where(g => g.Shared && g.Classes.Contains(cls)).Select(g => g.InterfaceName!).ToList();
            if (interfaces.Count == 0) continue;
            sb.AppendLine($"public {(cls.IsAbstract ? "abstract " : "")}partial class {cls.Name} : {string.Join(", ", interfaces)}");
            sb.AppendLine("{");
            sb.AppendLine("}");
            sb.AppendLine();
        }

        sb.AppendLine("/// <summary>Generated fluent setters: one <c>With…</c> family per model property. Each returns the object it was called on, keeping its static type.</summary>");
        sb.AppendLine("public static partial class LinkedArtExtensions");
        sb.AppendLine("{");
        foreach (var g in groups)
        {
            var constraint = g.Shared ? $"LinkedArtObject, {g.InterfaceName}" : g.Classes[0].Name;
            var owners = string.Join(", ", g.Classes.Select(c => c.Name));
            Emit(sb, g, constraint, owners);
        }
        sb.AppendLine("}");
        return sb.ToString();
    }

    private static void Emit(StringBuilder sb, Group g, string constraint, string owners)
    {
        var jsonName = JsonName(g);
        var type = g.PropertyType;
        var p = g.PropertyName;

        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>))
        {
            var item = type.GetGenericArguments()[0];
            var itemName = TypeName(item);
            sb.AppendLine($"    /// <summary>Appends to <c>{jsonName}</c> ({owners}).</summary>");
            sb.AppendLine($"    public static T With{p}<T>(this T obj, params {itemName}[] items) where T : {constraint}");
            sb.AppendLine("    {");
            sb.AppendLine($"        obj.{p} ??= [];");
            sb.AppendLine($"        obj.{p}.AddRange(items);");
            sb.AppendLine("        return obj;");
            sb.AppendLine("    }");
            sb.AppendLine();
            if (IsConcreteModel(item))
            {
                sb.AppendLine($"    /// <summary>Creates a <see cref=\"{itemName}\"/>, configures it, and appends it to <c>{jsonName}</c> ({owners}).</summary>");
                sb.AppendLine($"    public static T With{p}<T>(this T obj, Action<{itemName}> configure) where T : {constraint}");
                sb.AppendLine("    {");
                sb.AppendLine($"        var item = new {itemName}();");
                sb.AppendLine("        configure(item);");
                sb.AppendLine($"        obj.{p} ??= [];");
                sb.AppendLine($"        obj.{p}.Add(item);");
                sb.AppendLine("        return obj;");
                sb.AppendLine("    }");
                sb.AppendLine();
            }
            return;
        }

        var valueType = Nullable.GetUnderlyingType(type) ?? type;
        var valueName = TypeName(valueType);
        sb.AppendLine($"    /// <summary>Sets <c>{jsonName}</c> ({owners}).</summary>");
        sb.AppendLine($"    public static T With{p}<T>(this T obj, {valueName} value) where T : {constraint}");
        sb.AppendLine("    {");
        sb.AppendLine($"        obj.{p} = value;");
        sb.AppendLine("        return obj;");
        sb.AppendLine("    }");
        sb.AppendLine();
        if (IsConcreteModel(valueType))
        {
            sb.AppendLine($"    /// <summary>Creates a <see cref=\"{valueName}\"/>, configures it, and sets it as <c>{jsonName}</c> ({owners}).</summary>");
            sb.AppendLine($"    public static T With{p}<T>(this T obj, Action<{valueName}> configure) where T : {constraint}");
            sb.AppendLine("    {");
            sb.AppendLine($"        var value = new {valueName}();");
            sb.AppendLine("        configure(value);");
            sb.AppendLine($"        obj.{p} = value;");
            sb.AppendLine("        return obj;");
            sb.AppendLine("    }");
            sb.AppendLine();
        }
    }

    public static bool IsConcreteModel(System.Type t) =>
        typeof(LinkedArtObject).IsAssignableFrom(t) && !t.IsAbstract && t.GetConstructor(System.Type.EmptyTypes) is not null;

    private static string JsonName(Group g) =>
        g.Classes[0].GetProperty(g.PropertyName)!.GetCustomAttribute<System.Text.Json.Serialization.JsonPropertyNameAttribute>()?.Name ?? g.PropertyName;

    private static string Suffix(System.Type t)
    {
        var inner = t.IsGenericType ? t.GetGenericArguments()[0] : (Nullable.GetUnderlyingType(t) ?? t);
        return TypeName(inner).Replace("LinkedArt", "");
    }

    private static string TypeName(System.Type t)
    {
        if (t == typeof(string)) return "string";
        if (t == typeof(double)) return "double";
        if (t == typeof(int)) return "int";
        if (t == typeof(long)) return "long";
        if (t == typeof(bool)) return "bool";
        if (t.IsGenericType && t.GetGenericTypeDefinition() == typeof(List<>)) return $"List<{TypeName(t.GetGenericArguments()[0])}>";
        if (Nullable.GetUnderlyingType(t) is { } u) return TypeName(u) + "?";
        return t.Name;
    }
}
